// Montículo de mínimos (el de la clase de colas de prioridad): saca siempre el elemento que «va antes»
class Monticulo {
  constructor(antes) { this.a = []; this.antes = antes; }
  get tamano() { return this.a.length; }
  insertar(x) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.antes(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]]; i = p;
    }
  }
  extraer() {
    const a = this.a, primero = a[0], ultimo = a.pop();
    if (a.length > 0) {
      a[0] = ultimo; let i = 0;
      while (true) {
        let h = 2 * i + 1;
        if (h >= a.length) break;
        if (h + 1 < a.length && this.antes(a[h + 1], a[h])) h++;
        if (!this.antes(a[h], a[i])) break;
        [a[i], a[h]] = [a[h], a[i]]; i = h;
      }
    }
    return primero;
  }
}

