function dijkstra(origen, verPasos = false) {
  const dist = new Map();                           // mejor distancia conocida (provisoria hasta que se saca de la cola)
  dist.set(origen, 0);
  const padre = new Map();                          // de dónde viene el mejor camino conocido
  const listo = new Set();                          // ciudades con distancia definitiva
  const cola = new Monticulo((x, y) => x[0] < y[0]);
  cola.insertar([0, origen]);
  const orden = [];
  while (cola.tamano > 0) {
    const [d, u] = cola.extraer();
    if (listo.has(u)) continue;                     // entrada vieja: ya la sacamos con una distancia mejor
    listo.add(u); orden.push(u);
    const mejoras = [];
    for (const { a: v, km } of vecinos.get(u)) {
      if (listo.has(v)) continue;
      if (!dist.has(v) || d + km < dist.get(v)) {   // «relajar» la arista u-v: ¿pasar por u mejora el camino a v?
        dist.set(v, d + km); padre.set(v, u);
        cola.insertar([d + km, v]);
        mejoras.push(`${v} ${d + km}`);
      }
    }
    if (verPasos) console.log(`saco ${u} (${d})  mejoras: ${mejoras.join(", ") || "ninguna"}`);
  }
  return { dist, padre, orden };
}

