def dijkstra(origen):
    dist = {origen: 0}
    cola = [(0, origen)]                      # heapq es un montículo de mínimos sobre tuplas
    listo = set()
    while cola:
        d, u = heapq.heappop(cola)
        if u in listo:
            continue                          # entrada vieja
        listo.add(u)
        for v, km in vecinos[u]:
            if v not in listo and d + km < dist.get(v, float("inf")):
                dist[v] = d + km
                heapq.heappush(cola, (d + km, v))
    return dist

