function ciudad(L, semilla) {
  let s = semilla; const azar = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const V = L * L, ady = Array.from({ length: V }, () => []);
  let E = 0;
  for (let y = 0; y < L; y++) for (let x = 0; x < L; x++) {
    const u = y * L + x;
    for (const [dx, dy] of [[1, 0], [0, 1]]) {
      const nx = x + dx, ny = y + dy;
      if (nx < L && ny < L) { const v = ny * L + nx, w = 1 + Math.floor(azar() * 9); ady[u].push([v, w]); ady[v].push([u, w]); E++; }
    }
  }
  return { V, E, ady };
}
function conMonticulo(g, origen, destino) {
  const dist = new Float64Array(g.V).fill(Infinity), listo = new Uint8Array(g.V);
  dist[origen] = 0; const cola = new Monticulo((p, q) => p[0] < q[0]); cola.insertar([0, origen]);
  let sacados = 0, definitivos = 0, insertados = 1;
  while (cola.tamano > 0) {
    const [d, u] = cola.extraer(); sacados++;
    if (listo[u]) continue;
    listo[u] = 1; definitivos++;
    if (u === destino) break;                       // parar apenas sale el destino
    for (const [v, w] of g.ady[u]) if (d + w < dist[v]) { dist[v] = d + w; cola.insertar([d + w, v]); insertados++; }
  }
  return { d: dist[destino], sacados, definitivos, insertados };
}
function conBarrido(g, origen, destino) {            // sin cola: cada vez se busca el mínimo recorriendo TODOS los vértices
  const dist = new Float64Array(g.V).fill(Infinity), listo = new Uint8Array(g.V);
  dist[origen] = 0; let comparaciones = 0;
  for (let paso = 0; paso < g.V; paso++) {
    let u = -1;
    for (let i = 0; i < g.V; i++) { comparaciones++; if (!listo[i] && (u < 0 || dist[i] < dist[u])) u = i; }
    if (u < 0 || dist[u] === Infinity) break;
    listo[u] = 1;
    if (u === destino) break;
    for (const [v, w] of g.ady[u]) if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
  }
  return { d: dist[destino], comparaciones };
}
for (const L of [50, 100, 200, 300]) {
  const g = ciudad(L, 99), destino = g.V - 1;
  let t0 = performance.now(); const r = conMonticulo(g, 0, destino); const ms = performance.now() - t0;
  let linea = `L=${L}: V=${g.V.toLocaleString("es-AR")} E=${g.E.toLocaleString("es-AR")}  | montículo: ${r.d} min, ${r.definitivos.toLocaleString("es-AR")} definitivos, ${r.insertados.toLocaleString("es-AR")} inserciones, ${ms.toFixed(0)} ms`;
  if (L <= 100) { t0 = performance.now(); const b = conBarrido(g, 0, destino); const ms2 = performance.now() - t0; linea += `  | barrido: ${b.d} min, ${b.comparaciones.toLocaleString("es-AR")} comparaciones, ${ms2.toFixed(0)} ms`; }
