  }
}

// Tres vértices y una arista de peso NEGATIVO (por ejemplo, una ganancia por traer carga de vuelta). Datos inventados.
const aristas = [["s", "a", 2], ["s", "b", 5], ["b", "a", -10]];
const nodos = ["s", "a", "b"];

// Dijkstra simplificado: en cada vuelta fija al vértice más cercano de los que faltan y no lo revisa más
function dijkstraSimple(origen) {
  const dist = Object.fromEntries(nodos.map(n => [n, Infinity])); dist[origen] = 0;
  const listo = new Set();
  while (listo.size < nodos.length) {
    const u = nodos.filter(n => !listo.has(n)).sort((x, y) => dist[x] - dist[y])[0];
    listo.add(u);                                            // desde acá la distancia de u «es definitiva»
    for (const [x, y, w] of aristas) if (x === u && !listo.has(y) && dist[u] + w < dist[y]) dist[y] = dist[u] + w;
  }
  return dist;
}

// Bellman-Ford: repetir V-1 veces «relajar todas las aristas». Más lento, pero acepta pesos negativos
function bellmanFord(origen) {
  const dist = Object.fromEntries(nodos.map(n => [n, Infinity])); dist[origen] = 0;
  for (let vuelta = 1; vuelta < nodos.length; vuelta++)
    for (const [x, y, w] of aristas) if (dist[x] + w < dist[y]) dist[y] = dist[x] + w;
  return dist;
}
